package com.xdownload.mobile;
import android.content.Context;import android.net.Uri;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.regex.*;import java.util.zip.*;
/** Native aria2, no shell interpolation, private staging and no RPC listener. */
final class TorrentEngine{
 static File folder(Context c,String id){return new File(c.getFilesDir(),"torrent-"+id);}
 static File input(Context c,String id){return new File(folder(c,id),"input.torrent");}
 static boolean magnet(String value){if(value==null||value.length()>8192||!value.startsWith("magnet:?")||value.matches("(?s).*\\s.*"))return false;return Pattern.compile("(?:\\?|&)xt=urn:btih:(?:[a-fA-F0-9]{40}|[a-zA-Z2-7]{32})(?:&|$)").matcher(value).find();}
 static synchronized ProcessBuilder builder(Context c,List<String> args)throws Exception{MediaEngine.init(c);com.yausername.aria2c.Aria2c.getInstance().init(c.getApplicationContext());File root=new File(c.getNoBackupFilesDir(),"youtubedl-android/packages"),bin=new File(c.getApplicationInfo().nativeLibraryDir,"libaria2c.so");if(!bin.isFile())throw new IOException("Torrent native binary unavailable");ArrayList<String> cmd=new ArrayList<>();cmd.add(bin.getAbsolutePath());cmd.addAll(args);ProcessBuilder p=new ProcessBuilder(cmd).redirectErrorStream(true);p.environment().put("LD_LIBRARY_PATH",new File(root,"aria2c/usr/lib").getPath()+":"+new File(root,"python/usr/lib").getPath()+":"+new File(root,"ffmpeg/usr/lib").getPath());p.environment().put("HOME",c.getFilesDir().getAbsolutePath());p.environment().put("TMPDIR",c.getCacheDir().getAbsolutePath());return p;}
 static String version(Context c)throws Exception{Process p=builder(c,Arrays.asList("--version")).start();StringBuilder out=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()))){String line;while((line=r.readLine())!=null){if(out.length()>65536)throw new IOException("Unexpected version output");out.append(line).append('\n');}}if(p.waitFor()!=0||!out.toString().contains("BitTorrent"))throw new IOException("Native engine lacks BitTorrent");return out.toString();}
 static void importFile(Context c,Uri uri,Store.Job j)throws Exception{File dir=folder(c,j.id);if(!dir.mkdirs()&&!dir.isDirectory())throw new IOException("Cannot create torrent staging");boolean ok=false;try(InputStream in=c.getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(input(c,j.id))){if(in==null)throw new IOException("Cannot read torrent file");byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>4*1024*1024L)throw new IOException("Torrent metadata exceeds 4 MiB");out.write(b,0,n);}if(total==0)throw new IOException("Empty torrent file");out.getFD().sync();ok=true;}finally{if(!ok)cleanup(c,j.id);}}
 static File transfer(Context c,Store.Job j,HttpEngine.Observer observer)throws Exception{File dir=folder(c,j.id),payload=new File(dir,"payload");if(!payload.mkdirs()&&!payload.isDirectory())throw new IOException("Cannot create torrent directory");File file=input(c,j.id);if(!file.isFile()&&!magnet(j.url))throw new IOException("Invalid magnet or torrent metadata");File ca=new File(c.getNoBackupFilesDir(),"youtubedl-android/packages/python/usr/etc/tls/cert.pem");ArrayList<String> args=new ArrayList<>(Arrays.asList("--no-conf=true","--enable-rpc=false","--dir="+payload.getAbsolutePath(),"--file-allocation=none","--continue=true","--check-integrity=true","--seed-time=0","--summary-interval=1","--console-log-level=warn","--enable-color=false","--auto-save-interval=5","--bt-stop-timeout=120","--bt-max-peers=35","--enable-dht6=false","--enable-dht=true","--dht-file-path="+new File(dir,"dht.dat"),"--listen-port=0","--dht-listen-port=0","--max-upload-limit=512K","--ca-certificate="+ca.getAbsolutePath())); // ports replaced below with allowed range
 args.remove("--listen-port=0");args.remove("--dht-listen-port=0");args.add("--listen-port=49152-65535");args.add("--dht-listen-port=49152-65535");
 long rate=PerformancePolicy.rate(Store.settings(c).getInt("mode",1),Store.settings(c).getInt("rate_kib",0));if(rate>0)args.add("--max-download-limit="+rate);
 if(file.isFile())args.add("--torrent-file="+file.getAbsolutePath());else args.add(j.url);
 Process process=builder(c,args).directory(dir).start();AtomicBoolean finished=new AtomicBoolean();AtomicBoolean cancelled=new AtomicBoolean();Thread monitor=new Thread(()->{while(!finished.get()){if(!observer.proceed()||dir.getUsableSpace()<16*1024*1024L){cancelled.set(true);process.destroy();try{if(!process.waitFor(8,TimeUnit.SECONDS))process.destroyForcibly();}catch(InterruptedException ignored){process.destroyForcibly();}return;}try{Thread.sleep(500);}catch(InterruptedException ignored){return;}}});monitor.start();String last="";int code;try(BufferedReader reader=new BufferedReader(new InputStreamReader(process.getInputStream()))){String line;Pattern progress=Pattern.compile("\\((\\d{1,3})%\\)");while((line=reader.readLine())!=null){if(line.length()<400)last=line.replaceAll("https?://[^\\s]+","[url]").replaceAll("magnet:[^\\s]+","[magnet]");Matcher m=progress.matcher(line);if(m.find())j.mediaPercent=Math.min(99,Integer.parseInt(m.group(1)));observer.progress(0,-1,"","");}code=process.waitFor();}finally{finished.set(true);monitor.interrupt();if(process.isAlive())process.destroyForcibly();}
 if(cancelled.get()||!observer.proceed())return null;if(code!=0)throw new IOException("Torrent engine exit "+code+"; "+last);
 ArrayList<File> files=new ArrayList<>();collect(payload,payload,files);if(files.isEmpty())throw new IOException("Torrent has no completed files");if(files.size()==1){File out=files.get(0);j.name=HttpEngine.safeName(out.getName());j.mime="application/octet-stream";return out;}
 File archive=new File(dir,"completed.zip");long total=0;for(File f:files)total+=f.length();if(total+16*1024*1024L>dir.getUsableSpace())throw new IOException("Need additional space to package multi-file torrent");boolean ok=false;try(ZipOutputStream out=new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(archive)))){out.setLevel(0);byte[] b=new byte[65536];for(File f:files){if(!observer.proceed())return null;String relative=payload.toPath().relativize(f.toPath()).toString().replace(File.separatorChar,'/');out.putNextEntry(new ZipEntry(relative));try(InputStream in=new FileInputStream(f)){int n;while((n=in.read(b))!=-1){if(!observer.proceed())return null;out.write(b,0,n);}}out.closeEntry();}out.finish();ok=true;}finally{if(!ok)archive.delete();}j.name="Torrent-"+j.id.substring(0,8)+".zip";j.mime="application/zip";return archive;}
 static void collect(File base,File current,List<File> out)throws IOException{if(Files.isSymbolicLink(current.toPath())||!current.getCanonicalPath().startsWith(base.getCanonicalPath()+File.separator)&&!current.equals(base))throw new IOException("Unsafe torrent output path");if(current.isDirectory()){File[] list=current.listFiles();if(list==null)throw new IOException("Cannot list torrent files");for(File f:list)collect(base,f,out);}else{if(current.getName().endsWith(".aria2"))throw new IOException("Incomplete torrent control file");if(!current.isFile())throw new IOException("Invalid torrent output");out.add(current);if(out.size()>500)throw new IOException("Torrent file count exceeds 500");}}
 static void cleanup(Context c,String id){FileTools.deleteTree(folder(c,id));}
}